 final long S=0x7fff0000L,R=0x12345000L,G=0x5b6da4L,B=0x6151e0L;int rng;
 void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}String hex(byte[]a){StringBuilder s=new StringBuilder();for(byte b:a)s.append(String.format("%02x",b&255));return s.toString();}
 void call(EmulatorHelper e,long f,int x,int y)throws Exception{put(e,S,4,R);put(e,S+4,4,y);e.writeRegister("ESP",S);e.writeRegister("ECX",B);e.writeRegister("EDX",x);if(!e.run(toAddr(f),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=R){if(e.readRegister("EIP").longValue()!=0x460910)throw new Exception("Unexpected");rng++;if(!e.step(monitor)||!e.run(monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<32;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{rng=0;byte[]graph=new byte[96*136];for(int i=0;i<96;i++){for(int j=8;j<136;j++)graph[i*136+j]=(byte)(s*19+i*7+j*13);}e.writeMemory(toAddr(G),graph);int slot=s/2%4;for(int i=0;i<4;i++){put(e,G+i*136,2,400+i*128);put(e,G+i*136+2,2,512);put(e,G+i*136+4,2,480+i*128);put(e,G+i*136+6,2,576);}byte[]before=e.readMemory(toAddr(G),96*136);e.writeMemory(toAddr(B),new byte[32]);put(e,B,2,400+slot*128);put(e,B+2,2,512);put(e,B+4,2,80);put(e,B+6,2,64);put(e,B+12,2,s%2);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);e.setBreakpoint(toAddr(R));e.setBreakpoint(toAddr(0x460910));call(e,0x409690,416+slot*128,528);byte[]dead=e.readMemory(toAddr(G),96*136);call(e,0x409e70,400+slot*128,512);byte[]restored=e.readMemory(toAddr(G),96*136);StringBuilder changed=new StringBuilder();for(int i=0;i<dead.length;i++)if(dead[i]!=before[i]){if(changed.length()>0)changed.append(',');changed.append(i);}out.println("{\"scenario\":"+s+",\"slot\":"+slot+",\"changed\":["+changed+"],\"restoredEqual\":"+java.util.Arrays.equals(before,restored)+",\"saved\":\""+hex(e.readMemory(toAddr(0x615360),16))+"\",\"rng\":"+rng+",\"flag\":"+read(e,0x4a651b,1)+"}");out.flush();}finally{e.dispose();}}}}
